class Solution:
    def solve(self, nums: list) -> int:
        max_sum = 0
        for i in range(len(nums)):
            distinct_nums = set()
            current_sum = 0
            for j in range(i, len(nums)):
                if nums[j] not in distinct_nums:
                    distinct_nums.add(nums[j])
                    current_sum += nums[j]
                    max_sum = max(max_sum, current_sum)
                else:
                    break
        return max_sum

