class Solution:
       def solve(self, nums: list, target: int) -> list:
           def find_first(nums: list, target: int) -> int:
               left, right = 0, len(nums) - 1
               first_pos = -1
               while left <= right:
                   mid = (left + right) // 2
                   if nums[mid] < target:
                       left = mid + 1
                   else:
                       right = mid - 1
                       if nums[mid] == target:
                           first_pos = mid
               return first_pos

           def find_last(nums: list, target: int) -> int:
               left, right = 0, len(nums) - 1
               last_pos = -1
               while left <= right:
                   mid = (left + right) // 2
                   if nums[mid] > target:
                       right = mid - 1
                   else:
                       left = mid + 1
                       if nums[mid] == target:
                           last_pos = mid
               return last_pos

           start = find_first(nums, target)
           if start == -1:
               return [-1, -1]

           end = find_last(nums, target)
           return [start, end]

