class Solution:
       def solve(self, word: str, board: list) -> bool:
           # Write your code here
           def exists(i, j, k):
               if k == len(word):
                   return True
               if i < 0 or i >= len(board) or j < 0 or j >= len(board[0]) or word[k] != board[i][j]:
                   return False
               temp = board[i][j]
               board[i][j] = '#'
               found = exists(i + 1, j, k + 1) or exists(i - 1, j, k + 1) or exists(i, j + 1, k + 1) or exists(i, j - 1, k + 1)
               board[i][j] = temp
               return found
           for i in range(len(board)):
               for j in range(len(board[0])):
                   if exists(i, j, 0):
                       return True
           return False

